-- ============================================================================
-- CRMEB Java 单商户开源版 v3.0 -> v3.1 升级 SQL
-- CRMEB Java single merchant (open source) v3.0 -> v3.1 complete upgrade SQL
-- Baselines: sql/Crmeb_v3.0.sql (open source v3.0) -> sql/Crmeb_v3.1.sql (open source v3.1)
--
-- Includes: schema, menus/permissions, legacy route cleanup, config categories,
-- form templates, config-to-form mappings, notifications.
-- Preserves: orders, products, users, express data, roles, custom rows, and all
-- existing configuration values and unrelated custom rows outside v3.1 reserved IDs.
-- Features that are not part of the open-source edition (user level, statistics,
-- atmosphere/border, pickup verification & mobile admin, video channel, license)
-- are neither added nor re-enabled by this script.
--
-- IMPORTANT: back up the full database before execution. DDL implicitly commits in
-- MySQL, so the order_id change cannot be rolled back by the transaction below.
-- ============================================================================

SET NAMES utf8mb4;
SET @V31_OLD_FOREIGN_KEY_CHECKS := @@FOREIGN_KEY_CHECKS;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Schema change: coupon usage must record its associated order.
SET @V31_HAS_ORDER_ID := (
  SELECT COUNT(*) FROM `information_schema`.`COLUMNS`
  WHERE `TABLE_SCHEMA` = DATABASE()
    AND `TABLE_NAME` = 'eb_store_coupon_user'
    AND `COLUMN_NAME` = 'order_id'
);
SET @V31_DDL := IF(
  @V31_HAS_ORDER_ID = 0,
  'ALTER TABLE `eb_store_coupon_user` ADD COLUMN `order_id` int(11) NOT NULL DEFAULT 0 COMMENT ''关联订单id'' AFTER `primary_key`',
  'SELECT ''eb_store_coupon_user.order_id already exists'' AS message'
);
PREPARE V31_STMT FROM @V31_DDL;
EXECUTE V31_STMT;
DEALLOCATE PREPARE V31_STMT;

START TRANSACTION;

