-- Grant each new child to roles that already own its parent. Super administrators
-- bypass role-menu checks; ordinary roles inherit only within their existing scope.
INSERT INTO `eb_system_role_menu` (`rid`, `menu_id`)
SELECT DISTINCT parent_role.`rid`, child.`id`
FROM `eb_system_role_menu` AS parent_role
JOIN `eb_system_menu` AS child ON child.`pid` = parent_role.`menu_id`
WHERE (
  child.`perms` IN ('admin:system:config:clear:cache', 'admin:user:save', 'admin:recharge:refund', 'admin:user:update:password')
  OR child.`component` IN ('/maintain/clearCache')
  OR (child.`pid`, child.`perms`) IN (
    (75, 'admin:wechat:keywords:reply:save'),
    (77, 'admin:wechat:keywords:reply:save'),
    (77, 'admin:wechat:keywords:reply:update'),
    (91, 'admin:system:config:save:form'),
    (506, 'admin:theme:list'),
    (506, 'admin:theme:save:title'),
    (506, 'admin:theme:save:theme'),
    (506, 'admin:theme:save:image'),
    (506, 'admin:theme:use:data'),
    (506, 'admin:theme:restore'),
    (506, 'admin:theme:using'),
    (506, 'admin:theme:info'),
    (508, 'admin:theme:list'),
    (508, 'admin:theme:delete'),
    (508, 'admin:theme:save:title'),
    (508, 'admin:theme:save:theme'),
    (508, 'admin:theme:save:image'),
    (508, 'admin:theme:info')
  )
)
AND NOT EXISTS (
  SELECT 1 FROM `eb_system_role_menu` AS existing
  WHERE existing.`rid` = parent_role.`rid` AND existing.`menu_id` = child.`id`
);
-- Second pass: grant children whose parent was granted by the first pass (e.g. 清除缓存 under 缓存清理).
INSERT INTO `eb_system_role_menu` (`rid`, `menu_id`)
SELECT DISTINCT parent_role.`rid`, child.`id`
FROM `eb_system_role_menu` AS parent_role
JOIN `eb_system_menu` AS child ON child.`pid` = parent_role.`menu_id`
WHERE (
  child.`perms` IN ('admin:system:config:clear:cache', 'admin:user:save', 'admin:recharge:refund', 'admin:user:update:password')
  OR child.`component` IN ('/maintain/clearCache')
  OR (child.`pid`, child.`perms`) IN (
    (75, 'admin:wechat:keywords:reply:save'),
    (77, 'admin:wechat:keywords:reply:save'),
    (77, 'admin:wechat:keywords:reply:update'),
    (91, 'admin:system:config:save:form'),
    (506, 'admin:theme:list'),
    (506, 'admin:theme:save:title'),
    (506, 'admin:theme:save:theme'),
    (506, 'admin:theme:save:image'),
    (506, 'admin:theme:use:data'),
    (506, 'admin:theme:restore'),
    (506, 'admin:theme:using'),
    (506, 'admin:theme:info'),
    (508, 'admin:theme:list'),
    (508, 'admin:theme:delete'),
    (508, 'admin:theme:save:title'),
    (508, 'admin:theme:save:theme'),
    (508, 'admin:theme:save:image'),
    (508, 'admin:theme:info')
  )
)
AND NOT EXISTS (
  SELECT 1 FROM `eb_system_role_menu` AS existing
  WHERE existing.`rid` = parent_role.`rid` AND existing.`menu_id` = child.`id`
);

-- 2.3 Remove only the obsolete v3.0 entries replaced by v3.1 routes.
DELETE role_menu FROM `eb_system_role_menu` AS role_menu
JOIN `eb_system_menu` AS menu ON menu.`id` = role_menu.`menu_id`
WHERE (
  menu.`component` IN (
    '/javaMobile', '/javaMobile/orderCancellation', '/javaMobile/orderStatistics',
    '/operation/deliverGoods/takeGoods', '/maintain/logistics',
    '/operation/guide', '/operation/onePass',
    '/financial/commission', '/financial/record'
  )
  OR menu.`perms` IN (
    'admin:order:statistics', 'admin:order:statistics:data',
    'admin:order:write:confirm', 'admin:order:time',
    'admin:pass:appsave', 'admin:pass:appget'
  )
);
DELETE menu FROM `eb_system_menu` AS menu
WHERE (
  menu.`component` IN (
    '/javaMobile', '/javaMobile/orderCancellation', '/javaMobile/orderStatistics',
    '/operation/deliverGoods/takeGoods', '/maintain/logistics',
    '/operation/guide', '/operation/onePass',
    '/financial/commission', '/financial/record'
  )
  OR menu.`perms` IN (
    'admin:order:statistics', 'admin:order:statistics:data',
    'admin:order:write:confirm', 'admin:order:time',
    'admin:pass:appsave', 'admin:pass:appget'
  )
);

-- Open source: v3.0 left video-channel permission rows whose parent menus were
-- already removed; v3.1 drops the video-channel menus entirely.
DELETE role_menu FROM `eb_system_role_menu` AS role_menu
JOIN `eb_system_menu` AS menu ON menu.`id` = role_menu.`menu_id`
WHERE menu.`perms` LIKE 'admin:pay:component:%' OR menu.`perms` = 'admin:order:video:send'
   OR menu.`component` LIKE '/marketing/videoChannel%';
DELETE FROM `eb_system_menu`
WHERE `perms` LIKE 'admin:pay:component:%' OR `perms` = 'admin:order:video:send'
   OR `component` LIKE '/marketing/videoChannel%';

-- Remove role grants that point to menus which no longer exist.
DELETE role_menu FROM `eb_system_role_menu` AS role_menu
LEFT JOIN `eb_system_menu` AS menu ON menu.`id` = role_menu.`menu_id`
WHERE menu.`id` IS NULL;

