  `sort` = VALUES(`sort`),
  `update_time` = VALUES(`update_time`);

-- 3.1 Remove retired v3.0 config leaves to prevent duplicate categories.
DELETE FROM `eb_category` WHERE `type` = 6 AND `id` IN (93, 94, 96, 99, 101, 102, 104, 105, 107, 109, 110, 111, 112, 454, 501, 502, 503, 504, 592, 593, 624, 634, 635, 664, 693, 741, 756, 811, 812);

-- 4. Form templates.
-- Detach and remove the 30 superseded config forms; unknown custom forms are kept.
UPDATE `eb_system_config` SET `form_id` = 0, `update_time` = NOW() WHERE `form_id` IN (64, 65, 66, 67, 68, 74, 76, 77, 78, 80, 81, 82, 83, 108, 111, 122, 127, 128, 129, 134, 135, 137, 138, 141, 143, 144, 145, 146, 148, 149);
