-- pay_weixin_open intentionally appears in three payment forms; clone its current value.
SET @V31_PAY_WEIXIN_OPEN := COALESCE(
  (SELECT `value` FROM `eb_system_config` WHERE `name` = 'pay_weixin_open'
   ORDER BY (`status` = 0) DESC, `id` DESC LIMIT 1),
  '\'1\''
);
INSERT INTO `eb_system_config` (`name`, `title`, `form_id`, `value`, `status`, `create_time`, `update_time`) SELECT 'pay_weixin_open', 'pay_weixin_open', 163, @V31_PAY_WEIXIN_OPEN, 0, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM `eb_system_config` WHERE `name` = 'pay_weixin_open' AND `form_id` = 163);
INSERT INTO `eb_system_config` (`name`, `title`, `form_id`, `value`, `status`, `create_time`, `update_time`) SELECT 'pay_weixin_open', 'pay_weixin_open', 164, @V31_PAY_WEIXIN_OPEN, 0, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM `eb_system_config` WHERE `name` = 'pay_weixin_open' AND `form_id` = 164);
INSERT INTO `eb_system_config` (`name`, `title`, `form_id`, `value`, `status`, `create_time`, `update_time`) SELECT 'pay_weixin_open', 'pay_weixin_open', 165, @V31_PAY_WEIXIN_OPEN, 0, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM `eb_system_config` WHERE `name` = 'pay_weixin_open' AND `form_id` = 165);
UPDATE `eb_system_config` SET
  `title` = 'pay_weixin_open',
  `status` = IF(`form_id` IN (163, 164, 165), 0, 1),
  `form_id` = IF(`form_id` IN (163, 164, 165), `form_id`, 0),
  `update_time` = NOW()
WHERE `name` = 'pay_weixin_open';
DELETE FROM `eb_system_config` WHERE `name` = 'news_slides_limit';
-- Open source: store self-pickup is not included, keep it switched off.
UPDATE `eb_system_config` SET `value` = '0', `update_time` = NOW() WHERE `name` = 'store_self_mention';
-- Open source: the member level page is not included, drop its user-center entries.
DELETE FROM `eb_system_group_data`
WHERE `gid` = 54 AND `value` LIKE '%"value":"/pages/infos/user_vip/index"%';

-- 6. Preset DIY templates: v3.0 shipped image URLs pointing at a CRMEB test host.
-- Store them as relative paths so the API prefixes the current upload domain.
UPDATE `eb_page_diy`
SET `value` = REPLACE(REPLACE(`value`,
      'https://apia.beta.crmeb.xbdzz.cn/crmebimage/', 'crmebimage/'),
      'http://192.168.31.35:2040/crmebimage/', 'crmebimage/')
WHERE `value` LIKE '%apia.beta.crmeb.xbdzz.cn/crmebimage/%' OR `value` LIKE '%192.168.31.35:2040/crmebimage/%';

-- 7. Notification cleanup removed by v3.1 code.
DELETE FROM `eb_system_notification` WHERE `mark` = 'adminPlaceAnOrder';
DELETE FROM `eb_sms_template` WHERE `id` = 561 OR `temp_id` = '440405';

COMMIT;
SET FOREIGN_KEY_CHECKS = @V31_OLD_FOREIGN_KEY_CHECKS;

-- 8. Verification queries: expected issue_count is 0 for every row.
SELECT 'missing_order_id' AS check_name, IF(COUNT(*) = 1, 0, 1) AS issue_count
FROM `information_schema`.`COLUMNS` WHERE `TABLE_SCHEMA` = DATABASE()
  AND `TABLE_NAME` = 'eb_store_coupon_user' AND `COLUMN_NAME` = 'order_id';
SELECT 'missing_new_menu' AS check_name, 5 - COUNT(DISTINCT CASE
  WHEN `perms` IN ('admin:system:config:clear:cache', 'admin:user:save',
                    'admin:recharge:refund', 'admin:user:update:password') THEN `perms`
  WHEN `component` = '/maintain/clearCache' THEN `component` END) AS issue_count
FROM `eb_system_menu` WHERE `perms` IN ('admin:system:config:clear:cache',
  'admin:user:save', 'admin:recharge:refund', 'admin:user:update:password')
  OR `component` = '/maintain/clearCache';
SELECT 'missing_new_button' AS check_name, 18 - COUNT(*) AS issue_count
FROM `eb_system_menu` WHERE (`pid`, `perms`) IN (
    (75, 'admin:wechat:keywords:reply:save'),
    (77, 'admin:wechat:keywords:reply:save'),
    (77, 'admin:wechat:keywords:reply:update'),
    (91, 'admin:system:config:save:form'),
    (506, 'admin:theme:list'),
    (506, 'admin:theme:save:title'),
    (506, 'admin:theme:save:theme'),
    (506, 'admin:theme:save:image'),
    (506, 'admin:theme:use:data'),
    (506, 'admin:theme:restore'),
    (506, 'admin:theme:using'),
    (506, 'admin:theme:info'),
    (508, 'admin:theme:list'),
    (508, 'admin:theme:delete'),
    (508, 'admin:theme:save:title'),
    (508, 'admin:theme:save:theme'),
    (508, 'admin:theme:save:image'),
    (508, 'admin:theme:info')
  );
SELECT 'orphan_role_menu' AS check_name, COUNT(*) AS issue_count
FROM `eb_system_role_menu` AS role_menu LEFT JOIN `eb_system_menu` AS menu ON menu.`id` = role_menu.`menu_id`
WHERE menu.`id` IS NULL;
SELECT 'active_config_category_count' AS check_name, ABS(30 - COUNT(*)) AS issue_count
FROM `eb_category` WHERE `type` = 6 AND `status` = 1 AND `extra` REGEXP '^(15[0-9]|16[0-9]|17[0-9])$';
SELECT 'missing_config_form' AS check_name, COUNT(*) AS issue_count
FROM `eb_category` AS category LEFT JOIN `eb_system_form_temp` AS form
  ON form.`id` = CAST(category.`extra` AS UNSIGNED)
WHERE category.`type` = 6 AND category.`status` = 1
  AND category.`extra` REGEXP '^[0-9]+$' AND form.`id` IS NULL;
SELECT 'retired_config_category' AS check_name, COUNT(*) AS issue_count
FROM `eb_category` WHERE `type` = 6 AND `id` IN (93, 94, 96, 99, 101, 102, 104, 105, 107, 109, 110, 111, 112, 454, 501, 502, 503, 504, 592, 593, 624, 634, 635, 664, 693, 741, 756, 811, 812);
SELECT 'obsolete_metadata' AS check_name, COUNT(*) AS issue_count FROM (
  SELECT `id` FROM `eb_system_menu` WHERE `component` IN (
    '/javaMobile', '/javaMobile/orderCancellation', '/javaMobile/orderStatistics',
    '/operation/deliverGoods/takeGoods', '/maintain/logistics', '/operation/guide', '/operation/onePass'
  ) OR `perms` IN ('admin:pass:appsave', 'admin:pass:appget')
  UNION ALL
  SELECT `id` FROM `eb_system_notification` WHERE `mark` = 'adminPlaceAnOrder'
  UNION ALL
  SELECT `id` FROM `eb_system_config` WHERE `name` = 'news_slides_limit'
) AS obsolete;

